import { NextResponse } from 'next/server';

let users = [
    { id: 1, name: "João Silva", email: "joao@example.com", level: "Bronze", sales: 12, wallet: 450.00, status: "Ativo" },
    { id: 2, name: "Maria Oliveira", email: "maria@example.com", level: "Prata", sales: 45, wallet: 2800.00, status: "Ativo" },
    { id: 3, name: "Helio Vendedor", email: "helio@test.com", level: "Ouro", sales: 150, wallet: 12500.00, status: "Ativo" },
    { id: 4, name: "Ana Costa", email: "ana@example.com", level: "Bronze", sales: 5, wallet: 120.00, status: "Pendente" },
];

export async function GET() {
    return NextResponse.json(users);
}

export async function PUT(request: Request) {
    const data = await request.json();
    const { id, level, status } = data;

    const index = users.findIndex(u => u.id === id);
    if (index === -1) return NextResponse.json({ error: "User not found" }, { status: 404 });

    if (level) users[index].level = level;
    if (status) users[index].status = status;

    return NextResponse.json(users[index]);
}
